class Solution {
public:
    bool arrayStringsAreEqual(vector<string>& word1, vector<string>& word2) {
        int i = 0, j = 0;
        int ci = 0, cj = 0;
        int n1 = word1.size(), n2 = word2.size();
        while (i < n1 && j < n2) {
            if (word1[i][ci] != word2[j][cj]) return false;
            ci++;
            cj++;
            if (ci == (int)word1[i].size()) {
                i++;
                ci = 0;
            }
            if (cj == (int)word2[j].size()) {
                j++;
                cj = 0;
            }
        }
        return i == n1 && j == n2;
    }
};
